/// <summary>
/// Creates a <c>METSalesOrderWaveIdExtractEventContract</c> from a <c>DMFEntityExportDetails</c> record.
/// </summary>
/// <param name = "_salesId">SalesId</param>
/// <param name = "_waveId">WaveId</param>
/// <returns>A <c>METSalesOrderWaveIdExtractEventContract</c>.</returns>
public static METSalesOrderWaveGeneratedBusinessEventContract newFromSalesOrderExtractionDetails(SalesId _salesId, METWaveId _waveId)
{
    METSalesOrderWaveGeneratedBusinessEventContract contract = new METSalesOrderWaveGeneratedBusinessEventContract();
    contract.parmSalesId(_salesId);
    contract.parmWaveId(_waveId);
    return contract;
}

/// <summary>
/// Get or set sales id
