/// <returns>SalesId</returns>
[DataMember('SalesId'), BusinessEventsDataMember("@SYS4081954")]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;

    return salesId;
}

/// <summary>
