/// <returns>METWaveId</returns>
[DataMember('WaveId'), BusinessEventsDataMember("@MET:WaveId")]
public METWaveId parmWaveId(METWaveId _waveId = waveId)
{
    waveId = _waveId;

    return waveId;
}

